package dev.pedro.learning.ecommerce.notification.application;import dev.pedro.learning.ecommerce.notification.provider.FakeEmailProvider;import io.smallrye.faulttolerance.api.ExponentialBackoff;import jakarta.enterprise.context.ApplicationScoped;import org.eclipse.microprofile.faulttolerance.Retry;import java.time.temporal.ChronoUnit;import java.util.UUID;import java.util.concurrent.ConcurrentHashMap;import java.util.concurrent.atomic.AtomicInteger;@ApplicationScoped public class NotificationDeliveryService{private final FakeEmailProvider provider;private final ConcurrentHashMap<UUID,AtomicInteger> attempts=new ConcurrentHashMap<>();public NotificationDeliveryService(FakeEmailProvider provider){this.provider=provider;}@Retry(maxRetries=3,delay=250,delayUnit=ChronoUnit.MILLIS,jitter=0)@ExponentialBackoff(factor=2,maxDelay=2,maxDelayUnit=ChronoUnit.SECONDS)public void deliver(UUID eventId,UUID orderId,String email){attempts.computeIfAbsent(eventId,key->new AtomicInteger()).incrementAndGet();provider.send(email,"Order "+orderId+" confirmed");}public int attempts(UUID eventId){AtomicInteger count=attempts.get(eventId);return count==null?0:count.get();}public void clear(UUID eventId){attempts.remove(eventId);}}